<template>
 <view class="family-page gomoku-page">
  <view class="gomoku-hero"><view><text class="eyebrow">小妙棋社 · 观察与推理</text><text class="title">五子棋训练营</text><text class="hero-copy">想过对手的回应，再决定下一手。</text></view><image src="/static/ui/activities/gomoku.png" mode="aspectFit"/></view>
  <view class="mode-tabs"><button v-for="tab in tabs" :key="tab.id" :class="{active:mode===tab.id}" @click="switchMode(tab.id)">{{ tab.label }}</button></view>
  <view class="bank-overview"><text>共 {{ summary.total+tacticalPuzzles.length }} 个训练局面</text><text>单步 {{ summary.total }} 题 · 连续 {{ tacticalPuzzles.length }} 段</text></view>
  <text v-if="error" class="error">{{ error }}</text><button v-if="pending" class="secondary save-retry" @click="retrySave">重试保存这次练习</button>
  <view v-if="mode!=='tactics'" class="rule-note"><text>家庭自由规则</text><text>黑先，轮流下在交叉点；先连成五子或以上获胜，不设禁手。教学小棋盘 9×9，对弈棋盘 15×15。</text></view>
  <template v-if="mode==='learn'||mode==='practice'">
   <view class="course-heading"><text class="heading">{{ mode==='learn'?'8 个主题 · 随用随查':'按主题练习 · 每章都有新局面' }}</text><text>{{ summary.independent }} / {{ summary.total }} 题独立完成</text></view>
   <view class="lesson-tabs"><button v-for="(item,i) in lessons" :key="item.id" :class="{active:lessonIndex===i}" @click="selectLesson(i)"><text>{{ String(i+1).padStart(2,'0') }} · {{ item.puzzleIds.length }} 题</text><text>{{ item.title }}</text></button></view>
  </template>
  <view v-if="mode==='practice'" class="library-panel"><view class="library-heading"><text>本章 {{ lesson.puzzleIds.length }} 题 · 当前第 {{ lesson.puzzleIds.indexOf(puzzleId)+1 }} 题</text><button class="link" @click="practiceChooserOpen=!practiceChooserOpen">{{ practiceChooserOpen?'收起选题 −':'浏览本章题库 ＋' }}</button></view><template v-if="practiceChooserOpen"><view class="library-filters"><button v-for="item in difficulties" :key="item.id" :class="{active:practiceDifficulty===item.id}" :disabled="!hasPracticeDifficulty(item.id)" @click="setPracticeDifficulty(item.id)">{{ item.label }}</button></view><view class="question-grid"><button v-for="item in visiblePractice" :key="item.id" :class="{active:puzzleId===item.id}" @click="startPractice(item.id)"><text>{{ lesson.puzzleIds.indexOf(item.id)+1 }} · {{ difficultyLabel(item) }}</text><text>{{ item.title }}</text><text>{{ progress.independent.includes(item.id)?'★ 独立完成':progress.practiced.includes(item.id)?'✓ 已练习':item.skill||lesson.title }}</text></button></view><view class="library-pager"><button :disabled="practicePage===0" @click="practicePage--">上一页</button><text>{{ practicePage+1 }} / {{ practicePageCount }} 页 · {{ practiceList.length }} 题</text><button :disabled="practicePage+1>=practicePageCount" @click="practicePage++">下一页</button></view></template></view>
  <view v-if="mode==='tactics'" class="tactics-intro"><view class="course-heading"><text class="heading">看懂先手，走完攻防</text><text>{{ tacticalCompleted }} / {{ tacticalPuzzles.length }} 段完成</text></view><view class="library-heading"><text>当前：{{ difficultyLabel(tactic) }} · {{ tactic.skill||tactic.topic }}</text><button class="link" @click="tacticChooserOpen=!tacticChooserOpen">{{ tacticChooserOpen?'收起选题 −':'浏览 '+tacticalPuzzles.length+' 段题库 ＋' }}</button></view><template v-if="tacticChooserOpen"><view class="library-filters"><button v-for="item in difficulties" :key="item.id" :class="{active:tacticDifficulty===item.id}" :disabled="!hasTacticDifficulty(item.id)" @click="setTacticDifficulty(item.id)">{{ item.label }}</button></view><view class="library-filters kind-filters"><button :class="{active:tacticKind==='all'}" @click="setTacticKind('all')">全部目的</button><button :class="{active:tacticKind==='attack'}" @click="setTacticKind('attack')">进攻续算</button><button :class="{active:tacticKind==='defense'}" @click="setTacticKind('defense')">连续防守</button></view><view class="tactic-tabs"><button v-for="item in visibleTactics" :key="item.id" :class="{active:tacticId===item.id}" @click="startTactic(item.id)"><text>{{ tacticalPuzzles.indexOf(item)+1 }} · {{ difficultyLabel(item) }} · {{ item.skill||item.topic }}</text><text>{{ item.title }} {{ tacticalProgress.independent.includes(item.id)?'★':tacticalProgress.practiced.includes(item.id)?'✓':'' }}</text></button></view><text v-if="!tacticList.length" class="empty-bank">这个组合暂时没有题，可以切换难度或攻防目的。</text><view class="library-pager"><button :disabled="tacticPage===0" @click="tacticPage--">上一页</button><text>{{ tacticPage+1 }} / {{ tacticPageCount }} 页 · {{ tacticList.length }} 段</text><button :disabled="tacticPage+1>=tacticPageCount" @click="tacticPage++">下一页</button></view></template></view>
  <view v-if="mode==='play'" class="card game-settings"><view class="setting-row"><text>和谁下？</text><view><button :class="{active:opponent==='bot'}" @click="changeOpponent('bot')">小妙陪练</button><button :class="{active:opponent==='family'}" @click="changeOpponent('family')">同机双人</button></view></view><view v-if="opponent==='bot'" class="setting-row"><text>陪练节奏</text><view><button :class="{active:level==='gentle'}" @click="level='gentle'">入门</button><button :class="{active:level==='thoughtful'}" @click="level='thoughtful'">稳健陪练</button></view></view><text class="muted">{{ opponent==='bot'?'你执黑，小妙执白。留意对方威胁，也寻找自己的机会。':'黑白轮流落子，可以和家长一起说说为什么选这里。' }}</text></view>
  <view class="chess-layout">
   <view class="board-column"><view v-if="mode==='practice'" class="mission-strip"><text>{{ puzzle.title }} · {{ puzzle.toPlay===1?'执黑':'执白' }}</text><text>{{ puzzle.prompt }}</text></view>
    <view v-if="mode==='tactics'" class="mission-strip"><text>{{ tactic.title }} · {{ tactic.toPlay===1?'执黑':'执白' }} · 已思考 {{ tacticalState.childTurns }} 手</text><text>{{ tactic.prompt }}</text></view>
    <view class="board-top"><text>{{ boardTitle }}</text><text>{{ boardCaption }}</text></view>
    <view class="board-frame"><view class="column-labels" :style="{gridTemplateColumns:'repeat('+board.length+',1fr)'}"><text v-for="(_,c) in board" :key="c">{{ letters[c] }}</text></view><view class="board-with-rows"><view class="row-labels" :style="{gridTemplateRows:'repeat('+board.length+',1fr)'}"><text v-for="(_,r) in board" :key="r">{{ r+1 }}</text></view><view class="gomoku-board" :style="{gridTemplateColumns:'repeat('+board.length+',minmax(0,1fr))'}" :class="{'is-teaching':mode==='learn'}"><view v-for="(cell,i) in flatBoard" :key="i" :class="['intersection',{firstCol:i%board.length===0,lastCol:i%board.length===board.length-1,firstRow:i<board.length,lastRow:i>=board.length*(board.length-1),preview:isPoint(selected,i),reference:isPoint(reference,i),victory:hasPoint(winLine,i)}]" role="button" :aria-label="cellLabel(i,cell)" @click="selectPoint(Math.floor(i/board.length),i%board.length)"><view v-if="cell" :class="['stone',cell===1?'black':'white']"><view v-if="isPoint(lastMove,i)" class="last-dot"></view></view><view v-else-if="isPoint(selected,i)" :class="['ghost-stone',currentPlayer===1?'dark':'light']"></view><view v-else-if="isPoint(reference,i)" class="reference-dot"></view></view></view></view></view>
    <text class="board-legend">横、竖、两个斜向都要看。红点是最后一手，蓝圈是预选位置。</text>
    <template v-if="mode!=='learn'"><view class="selection-row"><text>{{ selected?'准备下在 '+coordinate(selected):'点一个空位预选，可以换位置再确认' }}</text><view :class="['turn-stone',currentPlayer===1?'black':'white']"></view></view><button v-if="!solved && gameStatus==='playing'" class="primary place" :disabled="!selected||thinking||paused" @click="confirmMove">{{ thinking?'小妙正在观察棋盘…':selected?'确认落子 · '+coordinate(selected):'先选一个交叉点' }}</button><button v-if="mode==='play'&&paused" class="primary place" @click="resumeGame">继续这一盘</button></template>
   </view>
   <view class="teaching-column">
    <view v-if="mode==='learn'" class="card lesson-card"><text class="eyebrow">第 {{ lessonIndex+1 }} 课 · {{ lesson.subtitle }}</text><text class="heading">{{ lesson.title }}</text><text class="body-copy">{{ lesson.observe }}</text><view class="formula"><text>记住这一句</text><text>{{ lesson.formula }}</text></view><text class="body-copy">{{ lesson.explanation }}</text><text class="mistake">容易忽略：{{ lesson.mistake }}</text><button class="primary" @click="startPractice(lesson.puzzleIds[0])">开始本章 {{ lesson.puzzleIds.length }} 题 →</button><text class="muted small-note">图中是本课第一道小棋题。学习之后，试着在棋盘上找到落点。</text></view>
    <view v-else-if="mode==='practice'" class="card practice-card"><text class="eyebrow">{{ lesson.title }} · 轮到{{ puzzle.toPlay===1?'黑棋':'白棋' }}</text><text class="heading">{{ puzzle.title }}</text><text class="body-copy">{{ puzzle.prompt }}</text><text class="question-position">第 {{ lesson.puzzleIds.indexOf(puzzleId)+1 }} / {{ lesson.puzzleIds.length }} 题 · {{ difficultyLabel(puzzle) }} · {{ puzzle.skill||lesson.title }}</text><view v-if="feedback" :class="['move-feedback',{success:solved}]"><text>{{ feedback }}</text></view><view v-if="!solved" class="hint-actions"><button class="secondary" @click="showHint">给一点线索</button><button class="link" @click="showReference">看一个参考落点</button></view><text v-if="hintText" class="hint-copy">{{ hintText }}</text><template v-if="solved"><text class="saved-copy">{{ pending?'练习已完成，进度还没保存':usedHelp||hadWrong?'这次练习已记下，理解后可以再独立试一次':'★ 这次独立完成，已保存在本机' }}</text><button class="primary" :disabled="!!pending" @click="nextPuzzle">{{ nextPuzzleLabel }}</button><button class="link" :disabled="!!pending" @click="startPractice(puzzleId)">重新独立挑战本题</button></template><text class="muted small-note">提示后做对也值得肯定。独立星记录每题未借助提示、未试错的一次完成，不重复累计。</text></view>
    <view v-else-if="mode==='tactics'" class="card tactics-card"><text class="eyebrow">{{ tactic.topic }} · {{ tacticalState.status==='playing'?'轮到你继续思考':tacticalSuccess?'攻防完成':'回看这一步' }}</text><text class="heading">{{ tacticalSuccess?'走完了，再说说为什么':tacticalState.status==='lost'?'这次对手先成五了':'对手怎样应，我怎样续？' }}</text><text class="body-copy">{{ feedback || tactic.goal }}</text><view v-if="tacticalState.history.length" class="round-log"><text v-for="(move,i) in tacticalState.history.slice(-4)" :key="tacticalState.history.length-4+i">{{ move.player===tactic.toPlay?'你':'对手' }} · {{ coordinate(move) }}：{{ move.reason }}</text></view><view v-if="tacticalState.status==='playing'" class="hint-actions"><button class="secondary" @click="tacticHint(false)">想法卡</button><button class="link" @click="tacticHint(true)">看参考落点</button></view><text v-if="hintText" class="hint-copy">{{ hintText }}</text><view v-if="tacticalState.status!=='playing'" class="tactic-review"><text>回看这段棋</text><text>{{ tactic.teaching.idea }}</text><text>容易误判：{{ tactic.teaching.trap }}</text><text>和家长聊聊：{{ tactic.teaching.reflection }}</text></view><text v-if="tacticalSuccess" class="saved-copy">{{ pending?'攻防已完成，进度还没保存':usedHelp||hadWrong?'这段练习已记下，可以重来一次独立完成':'★ 这段独立完成，已保存在本机' }}</text><view class="game-actions"><button class="secondary" :disabled="!tacticalSnapshots.length||!!pending" @click="undoTactic">退回这轮重想</button><button class="secondary" :disabled="!!pending" @click="startTactic(tacticId)">重新推演</button></view><button v-if="tacticalSuccess" class="primary" :disabled="!!pending" @click="nextTactic">下一段攻防 →</button><text class="muted small-note">观察对手的回应再走下一手。提示和回退帮助理解；同一题不反复发奖。</text></view>
    <view v-else class="card game-card"><text class="heading">{{ gameHeading }}</text><text class="body-copy">{{ feedback || '先想一想：我能直接成五吗？对方下一手能成五吗？' }}</text><text v-if="lastReason" class="coach-reason">{{ lastReason }}</text><view v-if="gameStatus!=='playing'" class="result-note"><text>{{ gameStatus==='draw'?'棋盘下满了，这盘和棋。':winner===1?'黑棋连成五子！':'白棋连成五子！' }}</text><text>一起复盘：最后的威胁从哪一手开始出现？</text><button class="link" @click="lessonIndex=2;startPractice(lessons[2].puzzleIds[0])">去练“先防成五” →</button></view><view class="game-actions"><button class="secondary" :disabled="!history.length" @click="undo">{{ opponent==='bot'?'退回自己上一手':'悔一手' }}</button><button class="secondary" :disabled="thinking||paused||gameStatus!=='playing'" @click="coachHint">帮我想一想</button></view><button class="link new-game" @click="requestNewGame">重新开一盘</button><button class="link" @click="showHistory=!showHistory">{{ showHistory?'收起棋谱 −':'看看本局落子 ＋' }}</button><view v-if="showHistory" class="move-list"><text v-for="(move,i) in history" :key="i">{{ i+1 }}. {{ move.player===1?'黑':'白' }} {{ coordinate(move) }}</text><text v-if="!history.length">从第一手开始留下棋谱。</text></view></view>
    <view class="card club-note"><view class="reflection-heading"><text class="heading">学会看棋，比背口诀更重要</text><view class="reflection-portrait"><family-portrait pose="thinking" fallback="/static/ui/activities/gomoku.png" mode="aspectFit" /></view></view><text class="muted">口诀是观察工具。连续攻防要看对手的反击和后续落点；棋形不熟时，可以打开手册对照。这里采用家庭自由规则，不训练比赛禁手。</text><button class="link" @click="goGrowth">看看我的探索成长 →</button><button class="link" @click="copySource">家长查阅棋形依据 · 复制链接</button></view>
   </view>
  </view>
 </view>
</template>
<script>
import { emptyBoard,placeStone,winningLine,boardFull,chooseGomokuMove,coachMove } from '@/game/gomoku.mjs'
import { lessons,puzzles,puzzleById } from '@/data/gomoku-lessons.mjs'
import { makePuzzleBoard,judgePuzzle,readGomokuLearning,summarizeGomokuLearning } from '@/game/gomoku-learning.mjs'
import { gomokuLearningStore } from '@/services/gomoku-learning.js'
import { tacticalPuzzles,createTacticalAttempt,playTacticalMove,tacticalHint,markTacticalHelp } from '@/game/gomoku-tactics.mjs'
import { tacticalProgressStore } from '@/services/gomoku-tactics.js'
export default {
 data(){return {tabs:[{id:'tactics',label:'连续攻防'},{id:'learn',label:'棋形手册'},{id:'practice',label:'题库练习'},{id:'play',label:'自由对弈'}],mode:'tactics',difficulties:[{id:'all',label:'全部'},{id:'observe',label:'棋形观察'},{id:'apply',label:'攻防应用'},{id:'challenge',label:'综合挑战'}],practiceDifficulty:'all',practicePage:0,practiceChooserOpen:false,tacticDifficulty:'all',tacticKind:'all',tacticPage:0,tacticChooserOpen:false,tacticalPuzzles,tacticId:tacticalPuzzles[0].id,tacticalState:createTacticalAttempt(tacticalPuzzles[0].id),tacticalSnapshots:[],tacticalProgress:readGomokuLearning(''),lessons,lessonIndex:0,puzzleId:puzzles[0].id,board:createTacticalAttempt(tacticalPuzzles[0].id).board,letters:'ABCDEFGHIJKLMNO',selected:null,reference:null,lastMove:null,winLine:[],feedback:'',hintText:'',usedHelp:false,hadWrong:false,solved:false,pending:null,progress:readGomokuLearning(''),error:'',opponent:'bot',level:'gentle',turn:1,history:[],winner:0,gameStatus:'playing',thinking:false,paused:false,botTimer:null,lastReason:'',showHistory:false,pageScroll:0}},
 computed:{
 practiceList(){return this.lesson.puzzleIds.map(id=>puzzleById[id]).filter(p=>this.practiceDifficulty==='all'||this.difficultyOf(p)===this.practiceDifficulty)},practicePageCount(){return Math.max(1,Math.ceil(this.practiceList.length/8))},visiblePractice(){return this.practiceList.slice(this.practicePage*8,this.practicePage*8+8)},
 tacticList(){return this.tacticalPuzzles.filter(p=>(this.tacticDifficulty==='all'||this.difficultyOf(p)===this.tacticDifficulty)&&(this.tacticKind==='all'||p.kind===this.tacticKind))},tacticPageCount(){return Math.max(1,Math.ceil(this.tacticList.length/6))},visibleTactics(){return this.tacticList.slice(this.tacticPage*6,this.tacticPage*6+6)},tacticalCompleted(){return this.tacticalPuzzles.filter(p=>this.tacticalProgress.practiced.includes(p.id)).length},
 tactic(){return this.tacticalPuzzles.find(p=>p.id===this.tacticId)},tacticalSuccess(){return ['won','defended'].includes(this.tacticalState.status)},
 lesson(){return this.lessons[this.lessonIndex]},puzzle(){return puzzleById[this.puzzleId]},flatBoard(){return this.board.flat()},summary(){return summarizeGomokuLearning(this.progress)},currentPlayer(){return this.mode==='play'?this.turn:this.mode==='tactics'?this.tactic.toPlay:this.puzzle.toPlay},boardTitle(){return this.mode==='tactics'?'9×9 · 连续攻防':this.mode==='play'?'15×15 · 实战小棋盘':this.mode==='learn'?'看一看这盘棋':'想一想，下在哪里？'},boardCaption(){return this.mode==='tactics'?(this.tacticalState.status==='playing'?'轮到你判断':this.tacticalSuccess?'完成整段':'观察对手的反击'):this.mode==='play'?this.gameHeading+' · '+this.history.length+' 手':(this.puzzle.toPlay===1?'黑':'白')+'棋先想'},gameHeading(){return this.gameStatus!=='playing'?'这盘棋，一起回看':this.paused?'已暂停，回来再想':this.thinking?'小妙正在想下一手':this.turn===1?'轮到黑棋':'轮到白棋'},nextPuzzleLabel(){const i=this.practiceList.findIndex(p=>p.id===this.puzzleId);return i<this.practiceList.length-1?'下一道练习 →':this.lessonIndex<this.lessons.length-1?'下一课 →':'去下盘棋，试试新诀窍 →'}
 },
 onPageScroll(event){this.pageScroll=event.scrollTop},
 onLoad(){this.readProgress()},onHide(){this.stopBot();if(this.mode==='play')this.paused=true},onShow(){this.readProgress()},onUnload(){this.stopBot()},
 onBackPress(){if(!this.pending)return false;uni.showModal({title:'这次练习还没保存',content:'可以留下重试，或放弃本次未保存的进度。',confirmText:'留下重试',cancelText:'放弃离开',success:r=>{if(r.cancel){this.pending=null;uni.navigateBack()}}});return true},
 methods:{
 difficultyOf(item){return item.difficulty||'observe'},difficultyLabel(item){return this.difficulties.find(d=>d.id===this.difficultyOf(item))?.label||'棋形观察'},
 hasPracticeDifficulty(level){return level==='all'||this.lesson.puzzleIds.some(id=>this.difficultyOf(puzzleById[id])===level)},
 hasTacticDifficulty(level){return level==='all'||this.tacticalPuzzles.some(p=>this.difficultyOf(p)===level)},
 setPracticeDifficulty(level){if(this.pending){this.error='先保存这次练习，再换难度。';return}if(!this.hasPracticeDifficulty(level))return;this.practiceDifficulty=level;this.practicePage=0},
 setTacticDifficulty(level){this.tacticDifficulty=level;this.tacticPage=0},setTacticKind(kind){this.tacticKind=kind;this.tacticPage=0},
 focusBoard(){this.$nextTick(()=>{uni.createSelectorQuery().in(this).select('.board-column').boundingClientRect(r=>{if(r)uni.pageScrollTo({scrollTop:Math.max(0,this.pageScroll+r.top-16),duration:180})}).exec()})},
 readProgress(){try{this.progress=gomokuLearningStore.read();this.tacticalProgress=tacticalProgressStore.read();if(!this.pending)this.error=''}catch(e){this.error=e.message}},coordinate(p){return this.letters[p.col]+(p.row+1)},isPoint(p,i){return !!p&&p.row===Math.floor(i/this.board.length)&&p.col===i%this.board.length},hasPoint(points,i){return points.some(p=>this.isPoint(p,i))},cellLabel(i,cell){return this.coordinate({row:Math.floor(i/this.board.length),col:i%this.board.length})+'，'+(cell===1?'黑棋':cell===2?'白棋':'空位')},
 stopBot(){clearTimeout(this.botTimer);this.botTimer=null;this.thinking=false},clearSelection(){this.selected=null;this.reference=null;this.winLine=[];this.lastMove=null;this.feedback='';this.hintText=''},
 selectLesson(index){if(this.pending){this.error='先保存这次完成的练习，再换一课。';return}this.stopBot();this.lessonIndex=index;this.puzzleId=this.lesson.puzzleIds[0];this.board=makePuzzleBoard(this.puzzle);this.clearSelection();if(this.mode==='practice')this.startPractice(this.puzzleId)},
 switchMode(mode){if(this.mode===mode)return;if(this.pending){this.error='先保存这次完成的练习，再切换。';return}this.stopBot();if(mode==='tactics')this.startTactic(this.tacticId);else if(mode==='play'){this.mode='play';this.newGame();this.focusBoard()}else if(mode==='practice')this.startPractice(this.lesson.puzzleIds[0]);else{this.mode='learn';this.puzzleId=this.lesson.puzzleIds[0];this.board=makePuzzleBoard(this.puzzle);this.clearSelection()}},
 startTactic(id){if(this.pending){this.error='先保存这段完成的攻防，再继续。';return}if(!this.tacticalPuzzles.some(p=>p.id===id))return;this.stopBot();this.mode='tactics';this.tacticId=id;if(!this.tacticList.some(p=>p.id===id)){this.tacticDifficulty='all';this.tacticKind='all'}this.tacticPage=Math.floor(this.tacticList.findIndex(p=>p.id===id)/6);this.tacticChooserOpen=false;this.tacticalState=createTacticalAttempt(id);this.board=this.tacticalState.board;this.tacticalSnapshots=[];this.clearSelection();this.usedHelp=false;this.hadWrong=false;this.solved=false;this.gameStatus='playing';this.paused=false;this.error='';this.focusBoard()},
 placeTactic(point){const before=this.tacticalState;const next=playTacticalMove(before,point.row,point.col);if(next.childTurns!==before.childTurns)this.tacticalSnapshots.push(before);this.tacticalState=next;this.board=next.board;this.lastMove=next.history[next.history.length-1]||null;this.feedback=next.feedback;this.hintText='';this.reference=null;this.hadWrong=this.hadWrong||!!next.mistakes;if(this.lastMove)this.winLine=winningLine(this.board,this.lastMove.row,this.lastMove.col);if(this.tacticalSuccess){this.solved=true;this.pending={kind:'tactics',id:this.tacticId,independent:!this.usedHelp&&!this.hadWrong};this.retrySave()}else if(next.status==='lost'){this.gameStatus='won';this.hadWrong=true}},
 tacticHint(reference){if(this.tacticalState.status!=='playing')return;this.usedHelp=true;this.tacticalState=markTacticalHelp(this.tacticalState);if(!reference){this.hintText=this.tactic.hint;return}const point=tacticalHint(this.tacticalState);this.reference=point;this.selected=null;this.hintText=point?'参考 '+this.coordinate(point)+'。'+point.reason:'暂时没有找到本任务的强制延续。可以退回上一轮，重新观察。';if(point)this.focusBoard()},
 undoTactic(){if(this.pending||!this.tacticalSnapshots.length)return;this.tacticalState=this.tacticalSnapshots.pop();this.board=this.tacticalState.board;this.usedHelp=true;this.hadWrong=true;this.solved=false;this.gameStatus='playing';this.clearSelection();this.lastMove=this.tacticalState.history[this.tacticalState.history.length-1]||null;this.feedback='退回了你和对手的这一轮。对照刚才的反击，再决定落点。'},
 nextTactic(){if(!this.tacticalSuccess||this.pending)return;const index=this.tacticList.findIndex(p=>p.id===this.tacticId);if(index<this.tacticList.length-1)this.startTactic(this.tacticList[index+1].id);else this.switchMode('play')},
 startPractice(id){if(this.pending){this.error='先保存这次完成的练习，再继续。';return}const p=puzzleById[id];if(!p)return;this.stopBot();this.mode='practice';this.lessonIndex=this.lessons.findIndex(l=>l.id===p.lessonId);this.puzzleId=id;if(!this.practiceList.some(item=>item.id===id))this.practiceDifficulty='all';this.practicePage=Math.floor(this.practiceList.findIndex(item=>item.id===id)/8);this.practiceChooserOpen=false;this.board=makePuzzleBoard(p);this.clearSelection();this.usedHelp=false;this.hadWrong=false;this.solved=false;this.gameStatus='playing';this.paused=false;this.error='';this.focusBoard()},
 selectPoint(row,col){if(this.mode==='learn'||this.solved||this.thinking||this.paused||this.gameStatus!=='playing')return;if(this.mode==='practice')this.board=makePuzzleBoard(this.puzzle);if(this.board[row][col]){this.feedback='这里已经有棋子，换一个空的交叉点试试。';return}this.selected={row,col};this.reference=null},
 confirmMove(){if(!this.selected||this.thinking||this.paused||this.solved||this.gameStatus!=='playing')return;const point={...this.selected};this.selected=null;if(this.mode==='tactics'){this.placeTactic(point);return}if(this.mode==='practice'){const result=judgePuzzle(this.puzzle,point.row,point.col);this.board=placeStone(makePuzzleBoard(this.puzzle),point.row,point.col,this.puzzle.toPlay);this.lastMove=point;this.feedback=result.feedback;if(!result.correct){this.hadWrong=true;return}this.solved=true;this.winLine=result.highlights||[];this.pending={id:this.puzzleId,independent:!this.usedHelp&&!this.hadWrong};this.retrySave();return}this.placeGame(point.row,point.col);if(this.gameStatus==='playing'&&this.opponent==='bot'&&this.turn===2)this.scheduleBot()},
 retrySave(){if(!this.pending)return;try{if(this.pending.kind==='tactics')this.tacticalProgress=tacticalProgressStore.save(this.tacticalState,{independent:this.pending.independent});else this.progress=gomokuLearningStore.save(this.pending.id,{independent:this.pending.independent});this.pending=null;this.error=''}catch(e){this.error='练习已完成，但进度还没保存：'+e.message}},
 showHint(){if(this.solved)return;this.usedHelp=true;this.hintText=this.puzzle.hint},showReference(){if(this.solved)return;this.usedHelp=true;this.selected=null;const initial=makePuzzleBoard(this.puzzle);for(let row=0;row<initial.length;row++)for(let col=0;col<initial.length;col++){if(!initial[row][col]&&judgePuzzle(this.puzzle,row,col).correct){this.board=initial;this.lastMove=null;this.reference={row,col};this.hintText='参考 '+this.coordinate(this.reference)+'。'+this.puzzle.hint;this.focusBoard();return}}},
 nextPuzzle(){if(!this.solved||this.pending)return;const i=this.practiceList.findIndex(p=>p.id===this.puzzleId);if(i<this.practiceList.length-1)this.startPractice(this.practiceList[i+1].id);else if(this.lessonIndex<this.lessons.length-1)this.startPractice(this.lessons[this.lessonIndex+1].puzzleIds[0]);else this.switchMode('play')},
 newGame(){this.stopBot();this.board=emptyBoard();this.history=[];this.turn=1;this.winner=0;this.gameStatus='playing';this.paused=false;this.solved=false;this.lastReason='';this.showHistory=false;this.clearSelection()},requestNewGame(){if(!this.history.length||this.gameStatus!=='playing'){this.newGame();return}uni.showModal({title:'重新开一盘？',content:'这盘棋的落子记录会重新开始。',success:r=>{if(r.confirm)this.newGame()}})},changeOpponent(opponent){if(opponent===this.opponent)return;if(!this.history.length||this.gameStatus!=='playing'){this.opponent=opponent;this.newGame();return}uni.showModal({title:'换一个对弈方式？',content:'会重新开始当前棋盘。',success:r=>{if(r.confirm){this.opponent=opponent;this.newGame()}}})},
 placeGame(row,col,reason=''){const player=this.turn;this.board=placeStone(this.board,row,col,player);const point={row,col,player};this.history.push(point);this.lastMove=point;this.selected=null;this.reference=null;this.winLine=winningLine(this.board,row,col);if(reason)this.lastReason='小妙下在 '+this.coordinate(point)+'：'+reason;this.feedback='';if(this.winLine.length){this.winner=player;this.gameStatus='won';this.stopBot()}else if(boardFull(this.board)){this.gameStatus='draw';this.stopBot()}else this.turn=3-player},
 scheduleBot(){this.stopBot();if(this.gameStatus!=='playing'||this.turn!==2||this.opponent!=='bot'||this.paused)return;this.thinking=true;this.botTimer=setTimeout(()=>{this.botTimer=null;try{const p=chooseGomokuMove(this.board,2,{level:this.level});this.thinking=false;if(p)this.placeGame(p.row,p.col,p.reason)}catch(e){this.thinking=false;this.paused=true;this.error='陪练暂时停下了：'+e.message}},280)},resumeGame(){this.paused=false;if(this.turn===2&&this.opponent==='bot')this.scheduleBot()},
 undo(){if(!this.history.length)return;this.stopBot();let count=1;if(this.opponent==='bot'&&this.history[this.history.length-1].player===2)count=2;this.history=this.history.slice(0,Math.max(0,this.history.length-count));this.board=emptyBoard();for(const p of this.history)this.board=placeStone(this.board,p.row,p.col,p.player);this.turn=this.history.length%2===0?1:2;this.gameStatus='playing';this.winner=0;this.paused=false;this.solved=false;this.clearSelection();this.lastMove=this.history[this.history.length-1]||null;this.lastReason='退回这一手后，再看看有没有更早的威胁。'},
 coachHint(){if(this.thinking||this.paused||this.gameStatus!=='playing')return;const p=coachMove(this.board,this.turn);if(!p)return;this.reference={row:p.row,col:p.col};this.selected=null;this.feedback='可以观察 '+this.coordinate(p)+'。'+p.reason},goGrowth(){uni.navigateTo({url:'/pages/growth/learning'})},copySource(){uni.setClipboardData({data:'https://www.renju.net/rules/'})}
 }
}
